##Supprimer tous les espaces inutiles dans une phrase.

CH=str(input())
def superflu (ch):
    while ch[0]==" ":
        ch=ch[1:]
    while ch.find("  ") != -1 :
        x = ch.find("  ")
        ch=ch[:x]+ch[x+1:]
    if ch[len(ch)-2]==(" "):
        ch = ch[:len(ch)-2]+ch[len(ch)-1]
    return ch
print(superflu(CH))

